EOF
npm run typecheck

cat << 'EOF' > fix.mjs
import fs from 'node:fs';

let content = fs.readFileSync('src/orchestration/tools/registry.ts', 'utf8');
content = content.replace(/import Ajv, \{/g, 'import { default as Ajv, ');
fs.writeFileSync('src/orchestration/tools/registry.ts', content);

let contentTest = fs.readFileSync('src/orchestration/tools/registry.test.ts', 'utf8');
contentTest = contentTest.replace(/import Ajv from 'ajv';/g, "import { default as Ajv } from 'ajv';");
fs.writeFileSync('src/orchestration/tools/registry.test.ts', contentTest);
EOF
node fix.mjs && npm run typecheck

